from datetime import datetime

def parse_dt(s):
    try:
        return datetime.fromisoformat(s.replace('Z','+00:00'))
    except Exception:
        return None

# find candidate t-shirt items in orders
candidates=[]
for o in orders:
    odt=parse_dt(o.get('created_at'))
    for it in o.get('order_items',[]):
        pn=(it.get('product_name') or '').lower()
        if any(k in pn for k in ['t-shirt','t shirt','tshirt','tee','t- shirt']):
            candidates.append({
                'order_id': o.get('order_id'),
                'order_created_at': o.get('created_at'),
                'product_id': it.get('product_id'),
                'product_name': it.get('product_name'),
                'product_color': o.get('color') if 'color' in o else it.get('color'),
                'item_created_dt': odt
            })

print('tshirt_item_candidates', len(candidates))
# show last 10 by created
candidates_sorted=sorted(candidates, key=lambda x: x['item_created_dt'] or datetime.min, reverse=True)
for c in candidates_sorted[:10]:
    print(c['order_id'], c['order_created_at'], c['product_id'], c['product_name'][:80] if c['product_name'] else None)

last_candidate=candidates_sorted[0] if candidates_sorted else None
print('last_candidate', last_candidate)

# Identify last t-shirt product in orders using stricter name matching
from datetime import datetime

def parse_dt(s):
    try:
        return datetime.fromisoformat(s.replace('Z','+00:00'))
    except Exception:
        return None

# stricter keyword: 't-shirt' or 't shirt' (with space) or 'short sleeve t' etc
import re
pattern = re.compile(r'\b(t[- ]?shirt|tee\b|t-shirt)\b', re.IGNORECASE)
# Actually 'tee' too broad; better look for 't-shirt' or 't shirt'
pattern2 = re.compile(r'(t[- ]shirt|t shirt)', re.IGNORECASE)

candidates=[]
for o in orders:
    odt=parse_dt(o.get('created_at'))
    for it in o.get('order_items',[]):
        pn=(it.get('product_name') or '')
        if pattern2.search(pn):
            candidates.append({
                'order_id': o.get('order_id'),
                'order_created_at': o.get('created_at'),
                'product_id': it.get('product_id'),
                'product_name': it.get('product_name'),
                'item_created_dt': odt
            })

print('tshirt candidates', len(candidates))
for c in sorted(candidates, key=lambda x: x['item_created_dt'], reverse=True)[:10]:
    print(c['order_id'], c['order_created_at'], c['product_id'], c['product_name'])

last = sorted(candidates, key=lambda x: x['item_created_dt'], reverse=True)[0] if candidates else None
print('last_tshirt', last)
